-- 汉帝国 / 刘备 —— 风云变幻规则集。只新增内容，不修改原版或其他文明。

VALUES('CIVILIZATION_HAN','LOC_CIVILIZATION_HAN_NAME','LOC_CIVILIZATION_HAN_DESCRIPTION','LOC_CIVILIZATION_HAN_ADJECTIVE','CIVILIZATION_LEVEL_FULL_CIV','ETHNICITY_ASIAN');
VALUES('LEADER_LIU_BEI','LOC_LEADER_LIU_BEI_NAME','LEADER_DEFAULT',0);
VALUES('LEADER_LIU_BEI','CIVILIZATION_HAN','LOC_CITY_NAME_HAN_CHENGDU');
-- 只沿用中国的市民姓名，不继承中国的能力。
SELECT 'CIVILIZATION_HAN',CitizenName,Female,Modern FROM CivilizationCitizenNames WHERE CivilizationType='CIVILIZATION_CHINA';

-- 三个文明特性 + 一个领袖特性。
-- 五虎将挂在单独的特性上：界面会把绑定了特色单位的特性当成单位而不是领袖能力（Civ6Common.lua GetLeaderUniqueTraits），
-- 挂在领袖能力特性上会让领袖能力整段不显示。做法同共产党 mod 的工农红军。

-- ============================================================
-- 兴复汉室：陆地作战单位迎战更强的单位时 +5（与高卢 Gaesatae 同一需求）；占领的城市每回合 +3 忠诚度。
-- ============================================================

-- ============================================================
-- 蜀道：陆地单位（含平民和支援单位）进入丘陵不额外消耗移动力（与阿尔卑斯训练相同）；
-- 每个相邻的山脉或丘陵为商业中心 +1 金币、为工业区 +1 生产力的标准相邻加成（与马丘比丘相同的修改器）。
-- ============================================================

-- 每种山脉、丘陵地形一条修改器，和马丘比丘（山脉）、马里（沙漠丘陵）的写法一致。
SELECT 'HAN_SHU_ROADS_'||d.Short||'_'||t.TerrainType,'MODIFIER_PLAYER_CITIES_TERRAIN_ADJACENCY'
FROM (SELECT 'COMMERCIAL' AS Short UNION ALL SELECT 'INDUSTRIAL') d, Terrains t WHERE t.Mountain=1 OR t.Hills=1;
SELECT 'HAN_SHU_ROADS_COMMERCIAL_'||TerrainType,'DistrictType','DISTRICT_COMMERCIAL_HUB' FROM Terrains WHERE Mountain=1 OR Hills=1
UNION ALL SELECT 'HAN_SHU_ROADS_COMMERCIAL_'||TerrainType,'TerrainType',TerrainType FROM Terrains WHERE Mountain=1 OR Hills=1
UNION ALL SELECT 'HAN_SHU_ROADS_COMMERCIAL_'||TerrainType,'YieldType','YIELD_GOLD' FROM Terrains WHERE Mountain=1 OR Hills=1
UNION ALL SELECT 'HAN_SHU_ROADS_COMMERCIAL_'||TerrainType,'Amount','1' FROM Terrains WHERE Mountain=1 OR Hills=1
UNION ALL SELECT 'HAN_SHU_ROADS_COMMERCIAL_'||TerrainType,'Description',
	CASE WHEN Mountain=1 THEN 'LOC_HAN_SHU_ROADS_MOUNTAIN_GOLD' ELSE 'LOC_HAN_SHU_ROADS_HILLS_GOLD' END FROM Terrains WHERE Mountain=1 OR Hills=1
UNION ALL SELECT 'HAN_SHU_ROADS_INDUSTRIAL_'||TerrainType,'DistrictType','DISTRICT_INDUSTRIAL_ZONE' FROM Terrains WHERE Mountain=1 OR Hills=1
UNION ALL SELECT 'HAN_SHU_ROADS_INDUSTRIAL_'||TerrainType,'TerrainType',TerrainType FROM Terrains WHERE Mountain=1 OR Hills=1
UNION ALL SELECT 'HAN_SHU_ROADS_INDUSTRIAL_'||TerrainType,'YieldType','YIELD_PRODUCTION' FROM Terrains WHERE Mountain=1 OR Hills=1
UNION ALL SELECT 'HAN_SHU_ROADS_INDUSTRIAL_'||TerrainType,'Amount','1' FROM Terrains WHERE Mountain=1 OR Hills=1
UNION ALL SELECT 'HAN_SHU_ROADS_INDUSTRIAL_'||TerrainType,'Description',
	CASE WHEN Mountain=1 THEN 'LOC_HAN_SHU_ROADS_MOUNTAIN_PRODUCTION' ELSE 'LOC_HAN_SHU_ROADS_HILLS_PRODUCTION' END FROM Terrains WHERE Mountain=1 OR Hills=1;
SELECT 'TRAIT_CIVILIZATION_HAN_SHU_ROADS',ModifierId FROM Modifiers WHERE ModifierId LIKE 'HAN_SHU_ROADS_COMMERCIAL_%' OR ModifierId LIKE 'HAN_SHU_ROADS_INDUSTRIAL_%';

-- ============================================================
-- 屯田：每个单位维护费 -1（与征兵政策相同）；与兵营相邻的任何改良设施（农场、矿山、种植园、营地、牧场、采石场等）+1 粮食、+1 生产力。
-- 地块条件：有改良设施 且 与兵营相邻。REQUIREMENT_PLOT_HAS_ANY_IMPROVEMENT 原版只用过反向（"没有改良设施"），这里用正向。
-- ============================================================

-- 屯田（续）：刘备不再获得大将军点数（见领袖部分的 -100%），兵营改为产出科技和金币。
-- 区域本身 +3 科技、+3 金币；兵营里每座原本产大将军点数的建筑按档次加科技和金币：军事学院 +6、军械库 +4，
-- 其余（兵营、马厩，以及征服模式激活来的 Ordu / Basilikoi Paides）+3。按原版数据生成。
SELECT 'HAN_TUNTIAN_ENCAMPMENT_'||Y,'MODIFIER_PLAYER_DISTRICTS_ADJUST_YIELD_CHANGE','HAN_DISTRICT_IS_ENCAMPMENT'
FROM (SELECT 'SCIENCE' AS Y UNION ALL SELECT 'GOLD');
SELECT 'HAN_TUNTIAN_ENCAMPMENT_'||Y,'YieldType','YIELD_'||Y FROM (SELECT 'SCIENCE' AS Y UNION ALL SELECT 'GOLD')
UNION ALL SELECT 'HAN_TUNTIAN_ENCAMPMENT_'||Y,'Amount',3 FROM (SELECT 'SCIENCE' AS Y UNION ALL SELECT 'GOLD');
SELECT 'TRAIT_CIVILIZATION_HAN_TUNTIAN','HAN_TUNTIAN_ENCAMPMENT_'||Y FROM (SELECT 'SCIENCE' AS Y UNION ALL SELECT 'GOLD');

SELECT 'HAN_TUNTIAN_'||y.Y||'_'||b.BuildingType,'MODIFIER_PLAYER_CITIES_ADJUST_BUILDING_YIELD_CHANGE'
FROM Buildings b JOIN Building_GreatPersonPoints g ON g.BuildingType=b.BuildingType, (SELECT 'SCIENCE' AS Y UNION ALL SELECT 'GOLD') y
WHERE b.PrereqDistrict='DISTRICT_ENCAMPMENT' AND g.GreatPersonClassType='GREAT_PERSON_CLASS_GENERAL';
SELECT 'HAN_TUNTIAN_'||y.Y||'_'||b.BuildingType,'BuildingType',b.BuildingType
FROM Buildings b JOIN Building_GreatPersonPoints g ON g.BuildingType=b.BuildingType, (SELECT 'SCIENCE' AS Y UNION ALL SELECT 'GOLD') y
WHERE b.PrereqDistrict='DISTRICT_ENCAMPMENT' AND g.GreatPersonClassType='GREAT_PERSON_CLASS_GENERAL'
UNION ALL
SELECT 'HAN_TUNTIAN_'||y.Y||'_'||b.BuildingType,'YieldType','YIELD_'||y.Y
FROM Buildings b JOIN Building_GreatPersonPoints g ON g.BuildingType=b.BuildingType, (SELECT 'SCIENCE' AS Y UNION ALL SELECT 'GOLD') y
WHERE b.PrereqDistrict='DISTRICT_ENCAMPMENT' AND g.GreatPersonClassType='GREAT_PERSON_CLASS_GENERAL'
UNION ALL
SELECT 'HAN_TUNTIAN_'||y.Y||'_'||b.BuildingType,'Amount',
	CASE b.BuildingType WHEN 'BUILDING_MILITARY_ACADEMY' THEN 6 WHEN 'BUILDING_ARMORY' THEN 4 ELSE 3 END
FROM Buildings b JOIN Building_GreatPersonPoints g ON g.BuildingType=b.BuildingType, (SELECT 'SCIENCE' AS Y UNION ALL SELECT 'GOLD') y
WHERE b.PrereqDistrict='DISTRICT_ENCAMPMENT' AND g.GreatPersonClassType='GREAT_PERSON_CLASS_GENERAL';
SELECT 'TRAIT_CIVILIZATION_HAN_TUNTIAN',ModifierId FROM Modifiers
WHERE ModifierId LIKE 'HAN_TUNTIAN_SCIENCE_%' OR ModifierId LIKE 'HAN_TUNTIAN_GOLD_%';

-- ============================================================
-- 桃园结义 · 五虎上将（领袖）
-- 武将不能训练或购买，由 Scripts/HanTigers.lua 在达成里程碑后免费送到首都，每人一生只送一次，阵亡不再出现。
-- 数值按远古时代给出，玩家每进入一个新时代 +8 战斗力（近战和远程攻击都算）。可以获得经验，晋升走各自的专属晋升树（Data/Promotions.sql），不能升级。
-- ============================================================


-- 兵种标签和 AI 行为沿用对应的原版单位，这样克制关系（如抗骑兵打骑兵 +10）和各类能力都照常生效。
SELECT 'UNIT_HAN_GUAN_YU',Tag FROM TypeTags WHERE Type='UNIT_KNIGHT'
UNION ALL SELECT 'UNIT_HAN_ZHANG_FEI',Tag FROM TypeTags WHERE Type='UNIT_SPEARMAN'
UNION ALL SELECT 'UNIT_HAN_ZHAO_YUN',Tag FROM TypeTags WHERE Type='UNIT_HORSEMAN'
UNION ALL SELECT 'UNIT_HAN_MA_CHAO',Tag FROM TypeTags WHERE Type='UNIT_HORSEMAN'
UNION ALL SELECT 'UNIT_HAN_HUANG_ZHONG',Tag FROM TypeTags WHERE Type='UNIT_ARCHER';
SELECT 'UNIT_HAN_GUAN_YU',AiType FROM UnitAiInfos WHERE UnitType='UNIT_KNIGHT'
UNION ALL SELECT 'UNIT_HAN_ZHANG_FEI',AiType FROM UnitAiInfos WHERE UnitType='UNIT_SPEARMAN'
UNION ALL SELECT 'UNIT_HAN_ZHAO_YUN',AiType FROM UnitAiInfos WHERE UnitType='UNIT_HORSEMAN'
UNION ALL SELECT 'UNIT_HAN_MA_CHAO',AiType FROM UnitAiInfos WHERE UnitType='UNIT_HORSEMAN'
UNION ALL SELECT 'UNIT_HAN_HUANG_ZHONG',AiType FROM UnitAiInfos WHERE UnitType='UNIT_ARCHER';

-- 各武将的专属能力（Inactive=0：带对应标签的单位自动拥有）。


-- 关羽 · 武圣：进攻时 +5；万军丛中：无视区域控制；过五关斩六将：击杀敌方单位后恢复 20 生命值（托米丽司的同类修改器）。
-- 破城（攻击所有时代的城墙都造成全额伤害）不在这里：攻城槌的 ENABLE_WALL_ATTACK 在风云变幻规则下只对远古城墙有效，
-- 改用全时代版本，挂在领袖特性上（见文件后面「领袖：关羽破城」）。
-- 斩首（进攻后残血的敌方单位直接斩杀）原版没有修改器，由 Scripts/HanTigers.lua 在战斗事件里实现。
('HAN_GUAN_YU_ATTACK','MODIFIER_UNIT_ADJUST_COMBAT_STRENGTH','HAN_UNIT_IS_ATTACKING'),
('HAN_GUAN_YU_KILL_HEAL','MODIFIER_PLAYER_UNIT_ADJUST_HEAL_FROM_COMBAT',NULL),
('HAN_GUAN_YU_IGNORE_ZOC','MODIFIER_PLAYER_UNIT_ADJUST_IGNORE_ZOC',NULL),
-- 张飞 · 万人敌：防守时 +7（抗骑兵兵种本身对骑兵另有 +10）。
('HAN_ZHANG_FEI_DEFENSE','MODIFIER_UNIT_ADJUST_COMBAT_STRENGTH','HAN_UNIT_IS_DEFENDING'),
-- 赵云 · 七进七出：无视区域控制，攻击后仍可移动。
('HAN_ZHAO_YUN_IGNORE_ZOC','MODIFIER_PLAYER_UNIT_ADJUST_IGNORE_ZOC',NULL),
('HAN_ZHAO_YUN_MOVE_AFTER_ATTACK','MODIFIER_PLAYER_UNIT_ADJUST_ATTACK_AND_MOVE',NULL),
-- 马超 · 西凉铁骑：侧翼加成 +100%；锦马超：对骑兵类单位 +5（原版抗骑兵用的同一需求组）。
('HAN_MA_CHAO_FLANKING','MODIFIER_PLAYER_UNIT_ADJUST_FLANKING_BONUS_MODIFIER',NULL),
('HAN_MA_CHAO_VS_CAVALRY','MODIFIER_UNIT_ADJUST_COMBAT_STRENGTH','ANTI_CAVALRY_OPPONENT_REQUIREMENTS'),
-- 黄忠 · 老当益壮：受伤不降低战斗力（武士同款）；定军山：对满血单位 +5。
('HAN_HUANG_ZHONG_NO_WOUND_PENALTY','MODIFIER_PLAYER_UNIT_ADJUST_NO_REDUCTION_DAMAGE',NULL),
('HAN_HUANG_ZHONG_VS_FULL_HEALTH','MODIFIER_UNIT_ADJUST_COMBAT_STRENGTH','HAN_OPPONENT_FULL_HEALTH');

-- 虎将之勇（五虎将通用）：生命值越低越强，用来保命。原版没有"按自身生命值"的战斗需求条件
-- （REQUIREMENT_UNIT_DAMAGE_MINIMUM 在战斗里判断的是对手），所以由 Scripts/HanTigers.lua 在回合开始和每次战斗后
-- 按生命值开关下面三档能力（Inactive，靠 ChangeAbilityCount 开启）。
-- 生命值低于 50 / 25 各 +7；张飞晋升「血战不退」后低于 75 也 +7。
SELECT 'ABILITY_HAN_TIGER_RAGE_'||Tier,'KIND_ABILITY' FROM (SELECT 25 AS Tier UNION ALL SELECT 50 UNION ALL SELECT 75);
SELECT 'ABILITY_HAN_TIGER_RAGE_'||Tier,'LOC_ABILITY_HAN_TIGER_RAGE_NAME','LOC_ABILITY_HAN_TIGER_RAGE_DESCRIPTION',1 FROM (SELECT 25 AS Tier UNION ALL SELECT 50 UNION ALL SELECT 75);
SELECT 'ABILITY_HAN_TIGER_RAGE_'||Tier,'CLASS_HAN_TIGER' FROM (SELECT 25 AS Tier UNION ALL SELECT 50 UNION ALL SELECT 75);
SELECT 'HAN_TIGER_RAGE_'||Tier,'MODIFIER_UNIT_ADJUST_COMBAT_STRENGTH' FROM (SELECT 25 AS Tier UNION ALL SELECT 50 UNION ALL SELECT 75);
SELECT 'HAN_TIGER_RAGE_'||Tier,'Amount',7 FROM (SELECT 25 AS Tier UNION ALL SELECT 50 UNION ALL SELECT 75);
SELECT 'HAN_TIGER_RAGE_'||Tier,'Preview','LOC_HAN_TIGER_RAGE_'||Tier||'_PREVIEW' FROM (SELECT 25 AS Tier UNION ALL SELECT 50 UNION ALL SELECT 75);
SELECT 'ABILITY_HAN_TIGER_RAGE_'||Tier,'HAN_TIGER_RAGE_'||Tier FROM (SELECT 25 AS Tier UNION ALL SELECT 50 UNION ALL SELECT 75);

-- 关羽 · 过五关斩六将（晋升）：每击杀一个敌方单位永久 +1 战斗力。由 Scripts/HanTigers.lua 按一生的击杀数开其中一档
