-- 统率：五虎将 2 格内（含自身所在格）的己方陆地作战单位 +5 战斗力、+1 移动力，像大将军但不受时代限制。
-- 范围条件复用大将军光环的 AOE_REQUIRES_OWNER_ADJACENCY（0~2 格）和 AOE_REQUIRES_LAND_DOMAIN，受益兵种照抄大将军能力的标签。
-- 用自己的能力而不是大将军的：可以和大将军叠加；同一个能力只生效一次，所以多位武将之间不叠加。
-- 发出光环的能力由 Scripts/HanTigers.lua 开关（Inactive=1）：平时开共用的 ABILITY_HAN_TIGER_COMMAND；
-- 诸葛亮学会「五虎齐心」后改开每位武将自己的 ABILITY_HAN_TIGER_COMMAND_<武将>，各自授予不同的能力，于是互相叠加。
SELECT 'ABILITY_HAN_TIGER_COMMANDED',Tag FROM TypeTags WHERE Type='ABILITY_GREAT_GENERAL_STRENGTH'
UNION ALL SELECT 'ABILITY_HAN_TIGER_COMMANDED_MOVEMENT',Tag FROM TypeTags WHERE Type='ABILITY_GREAT_GENERAL_MOVEMENT';

-- 五虎齐心（诸葛亮终极晋升）：每位武将自己的统率光环，授予各自不同的能力，所以多位武将互相叠加。
SELECT 'ABILITY_HAN_TIGER_COMMAND_'||T,'KIND_ABILITY' FROM (SELECT 'GUAN_YU' AS T UNION ALL SELECT 'ZHANG_FEI' AS T UNION ALL SELECT 'ZHAO_YUN' AS T UNION ALL SELECT 'MA_CHAO' AS T UNION ALL SELECT 'HUANG_ZHONG' AS T)
UNION ALL SELECT 'ABILITY_HAN_TIGER_COMMANDED_'||T,'KIND_ABILITY' FROM (SELECT 'GUAN_YU' AS T UNION ALL SELECT 'ZHANG_FEI' AS T UNION ALL SELECT 'ZHAO_YUN' AS T UNION ALL SELECT 'MA_CHAO' AS T UNION ALL SELECT 'HUANG_ZHONG' AS T);
SELECT 'ABILITY_HAN_TIGER_COMMAND_'||T,'LOC_ABILITY_HAN_TIGER_COMMAND_NAME','LOC_ABILITY_HAN_TIGER_COMMAND_DESCRIPTION',1 FROM (SELECT 'GUAN_YU' AS T UNION ALL SELECT 'ZHANG_FEI' AS T UNION ALL SELECT 'ZHAO_YUN' AS T UNION ALL SELECT 'MA_CHAO' AS T UNION ALL SELECT 'HUANG_ZHONG' AS T)
UNION ALL SELECT 'ABILITY_HAN_TIGER_COMMANDED_'||T,'LOC_ABILITY_HAN_TIGER_COMMAND_NAME','LOC_ABILITY_HAN_TIGER_COMMANDED_DESCRIPTION',1 FROM (SELECT 'GUAN_YU' AS T UNION ALL SELECT 'ZHANG_FEI' AS T UNION ALL SELECT 'ZHAO_YUN' AS T UNION ALL SELECT 'MA_CHAO' AS T UNION ALL SELECT 'HUANG_ZHONG' AS T);
SELECT 'ABILITY_HAN_TIGER_COMMAND_'||T,'CLASS_HAN_'||T FROM (SELECT 'GUAN_YU' AS T UNION ALL SELECT 'ZHANG_FEI' AS T UNION ALL SELECT 'ZHAO_YUN' AS T UNION ALL SELECT 'MA_CHAO' AS T UNION ALL SELECT 'HUANG_ZHONG' AS T);
SELECT 'ABILITY_HAN_TIGER_COMMANDED_'||t.T,g.Tag FROM (SELECT 'GUAN_YU' AS T UNION ALL SELECT 'ZHANG_FEI' AS T UNION ALL SELECT 'ZHAO_YUN' AS T UNION ALL SELECT 'MA_CHAO' AS T UNION ALL SELECT 'HUANG_ZHONG' AS T) t, TypeTags g WHERE g.Type='ABILITY_GREAT_GENERAL_STRENGTH';
SELECT 'HAN_TIGER_COMMAND_'||T,'MODIFIER_PLAYER_UNITS_GRANT_ABILITY','HAN_TIGER_COMMAND_RANGE' FROM (SELECT 'GUAN_YU' AS T UNION ALL SELECT 'ZHANG_FEI' AS T UNION ALL SELECT 'ZHAO_YUN' AS T UNION ALL SELECT 'MA_CHAO' AS T UNION ALL SELECT 'HUANG_ZHONG' AS T);
SELECT 'HAN_TIGER_COMMANDED_STRENGTH_'||T,'MODIFIER_UNIT_ADJUST_COMBAT_STRENGTH' FROM (SELECT 'GUAN_YU' AS T UNION ALL SELECT 'ZHANG_FEI' AS T UNION ALL SELECT 'ZHAO_YUN' AS T UNION ALL SELECT 'MA_CHAO' AS T UNION ALL SELECT 'HUANG_ZHONG' AS T)
UNION ALL SELECT 'HAN_TIGER_COMMANDED_MOVEMENT_'||T,'MODIFIER_PLAYER_UNIT_ADJUST_MOVEMENT' FROM (SELECT 'GUAN_YU' AS T UNION ALL SELECT 'ZHANG_FEI' AS T UNION ALL SELECT 'ZHAO_YUN' AS T UNION ALL SELECT 'MA_CHAO' AS T UNION ALL SELECT 'HUANG_ZHONG' AS T);
SELECT 'HAN_TIGER_COMMAND_'||T,'AbilityType','ABILITY_HAN_TIGER_COMMANDED_'||T FROM (SELECT 'GUAN_YU' AS T UNION ALL SELECT 'ZHANG_FEI' AS T UNION ALL SELECT 'ZHAO_YUN' AS T UNION ALL SELECT 'MA_CHAO' AS T UNION ALL SELECT 'HUANG_ZHONG' AS T)
UNION ALL SELECT 'HAN_TIGER_COMMANDED_STRENGTH_'||T,'Amount',5 FROM (SELECT 'GUAN_YU' AS T UNION ALL SELECT 'ZHANG_FEI' AS T UNION ALL SELECT 'ZHAO_YUN' AS T UNION ALL SELECT 'MA_CHAO' AS T UNION ALL SELECT 'HUANG_ZHONG' AS T)
UNION ALL SELECT 'HAN_TIGER_COMMANDED_MOVEMENT_'||T,'Amount',1 FROM (SELECT 'GUAN_YU' AS T UNION ALL SELECT 'ZHANG_FEI' AS T UNION ALL SELECT 'ZHAO_YUN' AS T UNION ALL SELECT 'MA_CHAO' AS T UNION ALL SELECT 'HUANG_ZHONG' AS T);
SELECT 'HAN_TIGER_COMMANDED_STRENGTH_'||T,'Preview','LOC_HAN_TIGER_COMMANDED_PREVIEW_'||T FROM (SELECT 'GUAN_YU' AS T UNION ALL SELECT 'ZHANG_FEI' AS T UNION ALL SELECT 'ZHAO_YUN' AS T UNION ALL SELECT 'MA_CHAO' AS T UNION ALL SELECT 'HUANG_ZHONG' AS T);
SELECT 'ABILITY_HAN_TIGER_COMMAND_'||T,'HAN_TIGER_COMMAND_'||T FROM (SELECT 'GUAN_YU' AS T UNION ALL SELECT 'ZHANG_FEI' AS T UNION ALL SELECT 'ZHAO_YUN' AS T UNION ALL SELECT 'MA_CHAO' AS T UNION ALL SELECT 'HUANG_ZHONG' AS T)
UNION ALL SELECT 'ABILITY_HAN_TIGER_COMMANDED_'||T,'HAN_TIGER_COMMANDED_STRENGTH_'||T FROM (SELECT 'GUAN_YU' AS T UNION ALL SELECT 'ZHANG_FEI' AS T UNION ALL SELECT 'ZHAO_YUN' AS T UNION ALL SELECT 'MA_CHAO' AS T UNION ALL SELECT 'HUANG_ZHONG' AS T)
UNION ALL SELECT 'ABILITY_HAN_TIGER_COMMANDED_'||T,'HAN_TIGER_COMMANDED_MOVEMENT_'||T FROM (SELECT 'GUAN_YU' AS T UNION ALL SELECT 'ZHANG_FEI' AS T UNION ALL SELECT 'ZHAO_YUN' AS T UNION ALL SELECT 'MA_CHAO' AS T UNION ALL SELECT 'HUANG_ZHONG' AS T);

-- ============================================================
-- 诸葛亮：支援单位（可与五虎将同格），不能训练或购买，拥有 3 座城市时由 Scripts/HanTigers.lua 送到首都旁，阵亡不再出现。
-- 2 格内（含同格）的五虎将：每回合额外恢复 15 生命值、+1 移动力、对空中单位 +25 战斗力（防空袭）。
-- 支援单位不参与战斗，经验由脚本给：2 格内的五虎将每打一仗，诸葛亮 +8 经验。晋升树见 Promotions.sql。
-- ============================================================
SELECT 'UNIT_HAN_ZHUGE_LIANG',AiType FROM UnitAiInfos WHERE UnitType='UNIT_MEDIC';
-- 范围：诸葛亮 0~2 格（复用大将军光环的距离条件）且是五虎将。

-- 领袖：所有单位的战斗经验 +100%（政策「测量」给侦察单位用的同一个修改器，这里不加兵种条件）。

-- 领袖：不获得大将军点数（所有来源，-100%；与原版作家点数 +50% 同一个修改器，用负数）。

-- 领袖：关羽破城。攻击所有时代的城墙都造成全额伤害。与阿卡德（城邦宗主）让近战单位整局全额攻城同一个修改器，
-- 按晋升类别判断；关羽有自己的晋升类别，所以只作用于关羽。

-- 张飞「丈八蛇矛」晋升用的全时代全额攻城：原版这个效果只有玩家级（作用于全部单位）的修改器类型，
-- 原版晋升里没有「单位拥有某晋升」的需求条件，所以新建一个作用于单位自己（COLLECTION_OWNER）的修改器类型，效果相同，在 Promotions.sql 使用。

-- 厚施恩德，以收众心：城市施加的忠诚度压力 +50%（与黄金时代同一修改器，可叠加）；
-- 叛离其他文明的城市在本文明忠诚压力最高时跳过自由城市直接归降（复用埃莉诺的 SKIP_FREE_CITY）。
SELECT 'TRAIT_LEADER_LIU_BEI_TIGERS',ModifierId FROM Modifiers WHERE ModifierId='SKIP_FREE_CITY';

-- 随时代成长：古典到未来每个时代一档，玩家时代达到该档就把 +8 的能力授予所有武将。
-- 古典（ChronologyIndex 2）起每个时代一档。时代只升不降，所以各档累加，不需要处理撤销；战斗预览里每档单独一行。
SELECT 'ABILITY_HAN_TIGER_'||EraType,'LOC_ABILITY_HAN_TIGER_ERA_NAME','LOC_ABILITY_HAN_TIGER_ERA_DESCRIPTION',1 FROM Eras WHERE ChronologyIndex >= 2;
SELECT 'ABILITY_HAN_TIGER_'||EraType,'CLASS_HAN_TIGER' FROM Eras WHERE ChronologyIndex >= 2;
SELECT 'HAN_REQ_PLAYER_'||EraType,'REQUIREMENT_PLAYER_ERA_AT_LEAST' FROM Eras WHERE ChronologyIndex >= 2;
SELECT 'HAN_REQ_PLAYER_'||EraType,'EraType',EraType FROM Eras WHERE ChronologyIndex >= 2;
SELECT 'HAN_PLAYER_'||EraType,'REQUIREMENTSET_TEST_ALL' FROM Eras WHERE ChronologyIndex >= 2;
SELECT 'HAN_PLAYER_'||EraType,'HAN_REQ_PLAYER_'||EraType FROM Eras WHERE ChronologyIndex >= 2;
SELECT 'HAN_GRANT_TIGER_'||EraType,'MODIFIER_PLAYER_UNITS_GRANT_ABILITY','HAN_PLAYER_'||EraType FROM Eras WHERE ChronologyIndex >= 2;
SELECT 'HAN_GRANT_TIGER_'||EraType,'AbilityType','ABILITY_HAN_TIGER_'||EraType FROM Eras WHERE ChronologyIndex >= 2;
SELECT 'HAN_TIGER_STRENGTH_'||EraType,'MODIFIER_UNIT_ADJUST_COMBAT_STRENGTH' FROM Eras WHERE ChronologyIndex >= 2;
SELECT 'HAN_TIGER_STRENGTH_'||EraType,'Amount',8 FROM Eras WHERE ChronologyIndex >= 2;
SELECT 'HAN_TIGER_STRENGTH_'||EraType,'Preview','LOC_HAN_TIGER_STRENGTH_PREVIEW_'||EraType FROM Eras WHERE ChronologyIndex >= 2;
SELECT 'ABILITY_HAN_TIGER_'||EraType,'HAN_TIGER_STRENGTH_'||EraType FROM Eras WHERE ChronologyIndex >= 2;
SELECT 'TRAIT_LEADER_LIU_BEI_TIGERS','HAN_GRANT_TIGER_'||EraType FROM Eras WHERE ChronologyIndex >= 2;
